select sa.id, sa.similar_score, sa.live_average_uv, sa.follower_count, sa.live_average_user, sa.live_average_amount, sa.total_amount, sa.live_total_amount_cmm_ind, sa.live_count, sa.live_average_online, sa.author_id, sa.unique_id, sa.sec_uid, sa.collect_date, sa.anchor_name, sa.anchor_avatar, sa.account_heat, sa.total_amount_numeric, sa.create_date, sa.update_date, sa.is_deleted, str.id AS similar_collect_id, str.source_type, str.system_anchor_id, str.pre_anchor_id, str.system_trade_id, str.last_update_system_trade_time, str.collect_status, str.up_ranking from tb_similar_anchor as sa join tb_hot_search_trade_ranking_list as str on sa.id = str.similar_anchor_id
join tb_anchor_url as au on str.system_anchor_id = au.id and au.platform = 0 join tb_anchor_crux_words_rela as acwr on acwr.sec_uid = au.sec_uid and acwr.is_deleted = 0 join tb_anchor_crux_words as acw on acwr.keyword_id = acw.id and acw.is_deleted = 0
where sa.is_deleted = 0 and str.is_deleted = 0
and sa.update_date >= DATE_SUB(NOW(), INTERVAL 30 DAY)
AND sa.update_date < DATE_SUB(NOW(), INTERVAL 30 DAY)
AND str.trade_id = #{tradeId}
AND str.up_ranking = #{upRanking}
