> 0
<= 0
AND sa.unique_id = #{uniqueId}
AND sa.anchor_name LIKE CONCAT('%', #{anchorName}, '%')
AND sa.account_heat >= #{heatStart}
AND sa.account_heat <= #{heatEnd}
AND sa.update_date >= #{updateTimeStart}
AND sa.update_date <= #{updateTimeEnd}
AND acw.keyword = #{liveKeyword}

